import GoalCategory from './classes/GoalCategory.js';
import Goal from './classes/Goal.js';
import TaskCategory from './classes/TaskCategory.js';
import Task from './classes/Task.js';
import JournalEntry from './classes/JournalEntry.js';

export default class Robi {
    // Properties
    static goal_categories = [];
    static journal_entries = [];
    static task_categories = [];
    static is_loaded = false;

    // Constants
    static GOAL_CATEGORY_STORAGE_KEY = 'ROBI_GoalCategories';
    static JOURNAL_ENTRY_STORAGE_KEY = 'ROBI_JournalEntries';
    static TASK_CATEGORY_STORAGE_KEY = 'ROBI_TaskCategories';

    // Public Methods
    static getGoalCategories() {
        this.load();
        return this.goal_categories;
    }
    static getJournalEntries() {
        this.load();
        return this.journal_entries;
    }
    static getTaskCategories() {
        this.load();
        return this.task_categories;
    }

    // Internal Methods
    static load() {
        if(!this.is_loaded) {
            this.loadGoalCategories();
            this.loadJournalEntries();
            this.loadTaskCategories();
            this.is_loaded = true;
        }
    }
    static save() {
        this.load();
        localStorage.setItem(this.GOAL_CATEGORY_STORAGE_KEY, JSON.stringify(this.goal_categories));
        localStorage.setItem(this.JOURNAL_ENTRY_STORAGE_KEY, JSON.stringify(this.journal_entries));
        localStorage.setItem(this.TASK_CATEGORY_STORAGE_KEY, JSON.stringify(this.task_categories));
    }
    static loadGoalCategories() {
        const obj_string = localStorage.getItem(this.GOAL_CATEGORY_STORAGE_KEY);
        if(!obj_string) {
            // Nothing in Local Storage... load Defaults
            this.goal_categories = this.getDefaultGoalCategories();
        } else {
            // Parse
            const obj_arr = JSON.parse(obj_string);
            this.goal_categories = [];
            obj_arr.forEach(obj => {
                const goal_category = new GoalCategory();
                goal_category.populateFromObj(obj);
                this.goal_categories.push(goal_category);
            });
        }
    }
    static getDefaultGoalCategories() {
        return [
            new GoalCategory('Short Term', [
                new Goal("Wake up everyday at 6:00am"),
                new Goal("Read in the Book of Mormon every day."),
                new Goal("Study a conference talk once per week."),
            ]),
            new GoalCategory('Long Term', [
                new Goal("Lose 75 pounds."),
                new Goal("Pay off all debts."),
                new Goal("Get a degree through Pathway."),
            ]),
        ]
    }
    static loadJournalEntries() {
        const obj_string = localStorage.getItem(this.JOURNAL_ENTRY_STORAGE_KEY);
        if(!obj_string) {
            // Nothing in Local Storage... load Defaults
            this.journal_entries = this.getDefaultJournalEntries();
        } else {
            // Parse
            const obj_arr = JSON.parse(obj_string);
            this.journal_entries = [];
            obj_arr.forEach(obj => {
                const journal_entry = new JournalEntry();
                journal_entry.populateFromObj(obj);
                this.journal_entries.push(journal_entry);
            });
        }
    }
    static getDefaultJournalEntries() {
        return [
            new JournalEntry(1754601604000, "Default Journal Entries", "Today I created default journal entries for my W06 project. I also went to the Asuncion Temple this morning.", "data:image/webp;base64,"),
            new JournalEntry(1754218800000, "Fast Sunday", "Today is Fast Sunday and I am very happy to be able to be in my own ward for once...", "data:image/webp;base64,"),
            new JournalEntry(294579000000, "It's My Birthday!", "Today I was born into the world! How can I write a journal entry for this? Magic...", "data:image/webp;base64,"),
        ]
    }
    static loadTaskCategories() {
        const obj_string = localStorage.getItem(this.TASK_CATEGORY_STORAGE_KEY);
        if(!obj_string) {
            // Nothing in Local Storage... load Defaults
            this.task_categories = this.getDefaultTaskCategories();
        } else {
            // Parse
            const obj_arr = JSON.parse(obj_string);
            this.task_categories = [];
            obj_arr.forEach(obj => {
                const task_category = new TaskCategory();
                task_category.populateFromObj(obj);
                this.task_categories.push(task_category);
            });
        }
    }
    static getDefaultTaskCategories() {
        return [
            new TaskCategory("Home/Pathway", [
                new Task("Populate Task Entries with Default Values", true),
                new Task("Finish WDD 131 W06 Final Project", false),
                new Task("Mow the lawn", false),
            ]),
            new TaskCategory("Church", [
                new Task("Meet with Local Celebration Committee", false),
                new Task("Prepare Class for this Sunday", false),
                new Task("Renew my Temple Recommend", true),
            ]),
            new TaskCategory("Work", [
                new Task("Test out v1.0.0 (20250805) of the app", false),
                new Task("Do Sprint Retrospective with iOS team", true),
                new Task("Research AWS Load Testing", false),
            ]),
        ];
    }
}